+.btn--primary{background:var(--red); color:#fff; box-shadow:0 10px 26px rgba(196,30,58,.22)}
+.btn--primary:hover{filter:brightness(.96)}
+.btn--ghost{background:transparent; border-color:rgba(15,23,42,.18); color:var(--ink)}
+.btn--ghost:hover{background:rgba(15,23,42,.04)}
+.btn--small{padding:9px 12px; border-radius:12px; font-weight:800}
+
+.menu-btn{
+  display:none;
+  width:44px; height:44px;
+  border-radius:14px;
+  border:1px solid rgba(15,23,42,.18);
+  background:#fff;
+  cursor:pointer;
