+.drawer__nav a{padding:10px 12px; border-radius:12px; text-decoration:none; font-weight:700; color:var(--slate)}
+.drawer__nav a:hover{background:rgba(15,23,42,.04); color:var(--ink)}
+.drawer__footer{margin-top:auto; padding:16px; border-top:1px solid rgba(15,23,42,.08); display:flex; flex-direction:column; gap:10px}
+
+.hero{
+  padding:54px 0 34px;
+  position:relative;
+  overflow:hidden;
+}
+.hero::before{
+  content:"";
+  position:absolute; inset:-60px -60px auto -60px; height:420px;
+  background:
+    radial-gradient(520px 320px at 16% 28%, rgba(196,30,58,.18), transparent 60%),
+    radial-gradient(520px 320px at 86% 30%, rgba(27,58,92,.14), transparent 58%),
+    linear-gradient(180deg, rgba(247,247,248,1), rgba(255,255,255,1));
+  z-index:-1;
+}
+.hero__grid{display:grid; grid-template-columns: 1.15fr .85fr; gap:28px; align-items:center}
+.kicker{display:inline-flex; align-items:center; gap:10px; color:var(--navy); font-weight:800; letter-spacing:.02em; font-size:14px}
+.kicker__dot{width:10px; height:10px; border-radius:999px; background:var(--red); box-shadow:0 0 0 5px rgba(196,30,58,.12)}
+.hero h1{font-size:48px; line-height:1.05; margin:12px 0 14px; letter-spacing:-.03em}
+.hero p{font-size:18px; color:var(--slate); margin:0 0 18px; max-width:56ch}
+.hero__ctas{display:flex; gap:12px; flex-wrap:wrap; margin-top:16px}
+.hero__note{margin-top:12px; font-size:14px; color:var(--muted)}
+
+.hero-card{
+  background:#fff;
+  border:1px solid rgba(15,23,42,.10);
+  border-radius:var(--radius);
+  box-shadow:var(--shadow);
+  overflow:hidden;
+}
+.hero-card__img{aspect-ratio: 4/3; background:var(--surface);}
+.hero-card__body{padding:16px}
+.hero-card__title{margin:0 0 6px; font-size:16px; letter-spacing:-.01em}
+.hero-card__meta{margin:0; color:var(--muted); font-size:14px}
+
+section{padding:54px 0}
+.section-head{display:flex; align-items:flex-end; justify-content:space-between; gap:18px; margin-bottom:18px}
+.section-head h2{margin:0; font-size:32px; letter-spacing:-.02em}
+.section-head p{margin:0; color:var(--muted); max-width:62ch}
+
+.prose{max-width:75ch; color:var(--slate)}
+.prose p{margin:0 0 14px}
+.prose strong{color:var(--ink)}
+
+.stats{
+  background:linear-gradient(180deg, var(--surface), #fff);
+  border-top:1px solid rgba(15,23,42,.08);
+  border-bottom:1px solid rgba(15,23,42,.08);
+}
+.stats-grid{display:grid; grid-template-columns:repeat(4, 1fr); gap:16px}
+.stat{
+  background:#fff;
+  border:1px solid rgba(15,23,42,.10);
+  border-radius:var(--radius);
+  padding:18px;
+  box-shadow:0 10px 22px rgba(15,23,42,.06);
+}
+.stat__num{font-size:34px; font-weight:900; letter-spacing:-.03em}
+.stat__label{margin-top:4px; color:var(--muted); font-weight:700}
+.stat__accent{height:4px; width:46px; border-radius:999px; background:var(--red); margin-top:12px}
+
+.programs-grid{display:grid; grid-template-columns:1fr 1fr; gap:16px}
+.accordion{
+  border:1px solid rgba(15,23,42,.10);
+  border-radius:var(--radius);
+  overflow:hidden;
+  background:#fff;
+}
+.acc-item + .acc-item{border-top:1px solid rgba(15,23,42,.08)}
+.acc-btn{
+  width:100%;
+  padding:16px 16px;
+  background:#fff;
+  border:0;
+  display:flex; align-items:center; justify-content:space-between; gap:14px;
+  cursor:pointer;
+  text-align:left;
+}
+.acc-title{font-weight:900; letter-spacing:-.01em}
+.acc-sub{color:var(--muted); font-weight:700; font-size:14px; margin-top:2px}
+.acc-icon{width:18px; height:18px; flex:0 0 auto; transition:transform 200ms ease}
+.acc-panel{max-height:0; overflow:hidden; transition:max-height 260ms ease; background:var(--surface)}
+.acc-panel__inner{padding:14px 16px; color:var(--slate)}
+.acc-panel__inner p{margin:0}
+.acc-item[data-open="true"] .acc-icon{transform:rotate(180deg)}
+
+.card-grid{display:grid; grid-template-columns:repeat(3, 1fr); gap:16px}
+.card{
+  background:#fff;
+  border:1px solid rgba(15,23,42,.10);
+  border-radius:var(--radius);
+  overflow:hidden;
+  box-shadow:0 10px 22px rgba(15,23,42,.06);
+}
+.card__img{aspect-ratio: 16/10; background:var(--surface)}
+.card__body{padding:16px}
+.card__title{margin:0 0 8px; font-size:18px; letter-spacing:-.01em}
+.card__text{margin:0 0 12px; color:var(--muted)}
+.card__cta{display:flex; align-items:center; gap:10px; color:var(--navy); font-weight:900; text-decoration:none}
+.card__cta:hover{text-decoration:underline}
+
+.news{
+  background:linear-gradient(180deg, #fff, var(--surface));
+}
+.carousel{
+  position:relative;
+}
+.carousel__viewport{overflow:hidden; border-radius:var(--radius)}
+.carousel__track{display:flex; gap:16px; transition:transform 320ms ease; will-change:transform}
+.news-card{flex:0 0 calc((100% - 32px)/3);}
+.carousel__controls{display:flex; gap:10px}
+.icon-btn{
+  width:44px; height:44px;
+  border-radius:14px;
+  border:1px solid rgba(15,23,42,.16);
+  background:#fff;
+  display:grid; place-items:center;
+  cursor:pointer;
+}
+.icon-btn:focus{outline:none; box-shadow:0 0 0 4px var(--ring)}
+.icon-btn[disabled]{opacity:.45; cursor:not-allowed}
+.icon-btn svg{width:18px; height:18px; fill:var(--slate)}
+
+.donate{
+  background:linear-gradient(180deg, rgba(196,30,58,.07), #fff);
+  border-top:1px solid rgba(15,23,42,.08);
+}
+.donate-grid{display:grid; grid-template-columns: 1.1fr .9fr; gap:16px; align-items:start}
+.donate-box{
+  background:#fff;
+  border:1px solid rgba(15,23,42,.10);
+  border-radius:var(--radius);
+  padding:18px;
+  box-shadow:var(--shadow);
+}
+.donate-box h3{margin:0 0 10px; font-size:22px; letter-spacing:-.02em}
+.donate-box p{margin:0 0 14px; color:var(--slate)}
