+.donate-table th{color:var(--muted); font-weight:900; letter-spacing:.02em; text-transform:uppercase; font-size:12px}
+
+.footer{
+  background:var(--navy);
+  color:#e7eef7;
+}
+.footer a{color:#e7eef7; text-decoration:none}
+.footer a:hover{text-decoration:underline}
+.footer-grid{display:grid; grid-template-columns: 1.1fr 1fr 1fr 1fr; gap:18px}
+.footer h4{margin:0 0 10px; font-size:14px; letter-spacing:.08em; text-transform:uppercase}
+.footer ul{list-style:none; padding:0; margin:0; display:flex; flex-direction:column; gap:8px}
+.footer__bottom{margin-top:18px; padding-top:18px; border-top:1px solid rgba(255,255,255,.16); display:flex; flex-wrap:wrap; gap:10px; align-items:center; justify-content:space-between}
+.social{display:flex; gap:10px; flex-wrap:wrap}
+.pill{display:inline-flex; padding:8px 10px; border-radius:999px; background:rgba(255,255,255,.12); font-weight:800; font-size:13px}
+
+/* Modal */
+.modal-backdrop{
+  position:fixed; inset:0;
+  background:rgba(15,23,42,.60);
+  display:none;
+  align-items:center;
+  justify-content:center;
+  padding:18px;
+  z-index:80;
+}
+.modal-backdrop[data-open="true"]{display:flex}
+.modal{
+  width:min(780px, 100%);
+  background:#fff;
+  border-radius:18px;
+  box-shadow:var(--shadow);
+  border:1px solid rgba(15,23,42,.12);
+  overflow:hidden;
+}
+.modal__header{display:flex; align-items:flex-start; justify-content:space-between; gap:12px; padding:16px 16px; border-bottom:1px solid rgba(15,23,42,.08)}
+.modal__title{margin:0; font-size:18px; letter-spacing:-.01em}
+.modal__subtitle{margin:4px 0 0; color:var(--muted); font-size:14px}
+.modal__close{width:44px; height:44px; border-radius:14px; border:1px solid rgba(15,23,42,.16); background:#fff; cursor:pointer}
+.modal__close:focus{outline:none; box-shadow:0 0 0 4px var(--ring)}
+.modal__close svg{width:18px; height:18px; fill:var(--slate)}
+.modal__body{padding:16px}
+.modal-grid{display:grid; grid-template-columns: 1.05fr .95fr; gap:16px}
+
+.amounts{display:grid; grid-template-columns:repeat(3, 1fr); gap:10px}
+.amount-btn{
+  padding:12px 12px;
+  border-radius:14px;
+  border:1px solid rgba(15,23,42,.16);
+  background:#fff;
+  cursor:pointer;
+  font-weight:900;
+}
+.amount-btn:hover{background:rgba(15,23,42,.04)}
+.amount-btn[aria-pressed="true"]{border-color:rgba(196,30,58,.55); box-shadow:0 0 0 4px rgba(196,30,58,.12)}
+
+.field{display:flex; flex-direction:column; gap:6px; margin-top:12px}
+.field label{font-weight:800; color:var(--slate); font-size:14px}
+.field input,.field select{
+  padding:12px 12px;
+  border-radius:14px;
+  border:1px solid rgba(15,23,42,.18);
+  font:inherit;
+}
+.field input:focus,.field select:focus{outline:none; box-shadow:0 0 0 4px var(--ring)}
+.helper{color:var(--muted); font-size:13px; margin-top:8px}
+
+.summary{
+  background:var(--surface);
+  border:1px solid rgba(15,23,42,.10);
+  border-radius:var(--radius);
+  padding:14px;
+}
+.summary h4{margin:0 0 10px; letter-spacing:-.01em}
+.summary-row{display:flex; align-items:flex-start; justify-content:space-between; gap:10px; padding:8px 0; border-bottom:1px solid rgba(15,23,42,.08)}
+.summary-row:last-child{border-bottom:0}
+.summary dt{color:var(--muted); font-weight:800}
+.summary dd{margin:0; font-weight:900; text-align:right}
+
+.modal__footer{display:flex; gap:10px; justify-content:flex-end; padding:14px 16px; border-top:1px solid rgba(15,23,42,.08); background:#fff}
+
+/* Reduced motion */
+@media (prefers-reduced-motion: reduce){
+  html{scroll-behavior:auto}
+  .carousel__track,.acc-panel,.drawer,.drawer-backdrop{transition:none !important}
+}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero__grid{grid-template-columns:1fr;}
+  .donate-grid{grid-template-columns:1fr}
+  .modal-grid{grid-template-columns:1fr}
+  .news-card{flex:0 0 calc((100% - 16px)/2)}
+  .card-grid{grid-template-columns:repeat(2, 1fr)}
+  .footer-grid{grid-template-columns: 1fr 1fr}
+  .programs-grid{grid-template-columns:1fr}
+}
+
+@media (max-width: 720px){
+  .nav__links,.nav__donate{display:none}
+  .menu-btn{display:inline-grid; place-items:center}
+  .hero h1{font-size:38px}
+  .stats-grid{grid-template-columns:repeat(2, 1fr)}
+  .news-card{flex:0 0 100%}
+  .card-grid{grid-template-columns:1fr}
+}
+
+@media (max-width: 420px){
+  .hero h1{font-size:34px}
+  .amounts{grid-template-columns:repeat(2, 1fr)}
+}
+
*** End Patch
PATCH

